"""Entry point following the same contract as engines generated by the coding agent.

``run_engine(case)`` returns ``{"trace_steps": [...], "summary": {...}}``, where the
summary holds the keys from the domain pack's output contract. The optional
``mock_llm_judge`` argument supplies recorded judgments, so golden tests run offline.
"""

from .income_engine import run_engine as _run_income_engine


def run_engine(case: dict, mock_llm_judge: dict = None) -> dict:
    result = _run_income_engine(case, mock_llm_judge=mock_llm_judge)
    trace = result['trace']

    step_decisions, step_values = {}, {}
    for step in trace:  # first occurrence wins when a step runs once per borrower
        step_decisions.setdefault(step['step_id'], step['decision'])
        if isinstance(step.get('result_value'), (int, float)):
            step_values.setdefault(step['step_id'], step['result_value'])

    return {
        'trace_steps': trace,
        'summary': {
            **result['summary'],
            'flags': result['flags'],
            'conditions': result['conditions'],
            'income': result['income'],
            'step_decisions': step_decisions,
            'step_values': step_values,
        },
    }
